/** 变更后有效期止可选起始判断：须晚于原有效期止（同一天不可选） */
export function isExtendValidToDisabled(origValidTo, time) {
  if (!origValidTo) return false
  const from = new Date(formatDateOnly(origValidTo).replace(/-/g, '/'))
  if (Number.isNaN(from.getTime())) return false
  return new Date(time).setHours(0, 0, 0, 0) <= from.setHours(0, 0, 0, 0)
}

/** 日期面板默认展示月：原有效期止的下一自然日所在月，避免打开后整月不可选 */
export function getExtendValidToDefaultValue(origValidTo) {
  const from = new Date(formatDateOnly(origValidTo).replace(/-/g, '/'))
  if (Number.isNaN(from.getTime())) return undefined
  from.setHours(0, 0, 0, 0)
  from.setDate(from.getDate() + 1)
  return from
}

